   908  static int vcardparser_parse(struct vcardparser_state *state, int only_one)
   909  {
   910      state->root = vcardcomponent_new(VCARD_XROOT_COMPONENT);
   911
   912      state->p = state->base;
   913
   914      buf_init(&state->buf, BUF_GROW);
   915
   916      /* don't parse trailing non-whitespace */
   917      return _parse_vcard(state, state->root, only_one);
   918  }
